import React, { useState, useEffect, useCallback } from 'react';
import {
  View,
  Text as NativeText,
  TextInput,
  Pressable,
  StyleSheet,
  ScrollView,
  KeyboardAvoidingView,
  TouchableWithoutFeedback,
  Keyboard,
  Platform,
} from 'react-native';
import { BottomSheetModal, BottomSheetView, BottomSheetBackdrop } from '@gorhom/bottom-sheet';
import { MaterialCommunityIcons } from '@expo/vector-icons';
import { Category, CATEGORY_LABELS, TransactionType } from '../types/transaction';
import { useTransactionStore } from '../store/useTransactionStore';
import { useSettingsStore } from '../store/useSettingsStore';
import { useTranslation } from '../utils/translations';
import { getThemeColors, ThemedText } from '../utils/theme';

interface TransactionBottomSheetProps {
  bottomSheetRef: React.RefObject<BottomSheetModal | null>;
  initialType?: TransactionType;
}

const CATEGORIES = Object.keys(CATEGORY_LABELS) as Category[];
const Text = ThemedText;

export default function TransactionBottomSheet({
  bottomSheetRef,
  initialType = 'gasto',
}: TransactionBottomSheetProps) {
  const addTransaction = useTransactionStore((s) => s.addTransaction);
  const accentColor = useSettingsStore((s) => s.accentColor);
  const appTheme = useSettingsStore((s) => s.theme);
  const theme = getThemeColors(appTheme);
  const { t } = useTranslation();

  const [type, setType] = useState<TransactionType>(initialType);
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState<Category>(
    initialType === 'ingreso' ? 'salario' : 'comida'
  );
  const [note, setNote] = useState('');
  const [amountError, setAmountError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    setType(initialType);
    setCategory(initialType === 'ingreso' ? 'salario' : 'comida');
  }, [initialType]);

  const handleSubmit = async () => {
    const numericAmount = parseFloat(amount.replace(',', '.'));
    if (!Number.isFinite(numericAmount) || numericAmount <= 0) {
      setAmountError('Ingresa un monto mayor que cero.');
      return;
    }

    setAmountError('');
    setIsSubmitting(true);

    try {
      await addTransaction({
        amount: numericAmount,
        type,
        category,
        date: new Date().toISOString(),
        note: note.trim() || undefined,
      });

      Keyboard.dismiss();
      setAmount('');
      setNote('');
      bottomSheetRef.current?.dismiss();
    } finally {
      setIsSubmitting(false);
    }
  };

  const renderBackdrop = useCallback(
    (props: any) => (
      <BottomSheetBackdrop
        {...props}
        disappearsOnIndex={-1}
        appearsOnIndex={0}
        opacity={0.5}
      />
    ),
    []
  );

  return (
    <BottomSheetModal
      ref={bottomSheetRef}
      index={0}
      snapPoints={['65%']}
      backdropComponent={renderBackdrop}
      enablePanDownToClose
    >
      <TouchableWithoutFeedback onPress={Keyboard.dismiss}>
        <BottomSheetView style={[styles.contentContainer, { backgroundColor: theme.surface }]}>
        <View style={styles.handleBar} />

        <View style={styles.header}>
          <View>
            <Text style={[styles.title, { color: theme.text }]}>{t('Registrar Movimiento')}</Text>
            <Text style={[styles.subtitle, { color: theme.textSecondary }]}>Financia Smart Bank</Text>
          </View>
        </View>

        <KeyboardAvoidingView
          behavior={Platform.OS === 'ios' ? 'padding' : undefined}
          style={{ flex: 1 }}
        >
          <View style={styles.typeSwitch}>
            <Pressable
              style={[styles.typeButton, type === 'gasto' && styles.typeButtonActiveExpense]}
              onPress={() => setType('gasto')}
            >
              <View style={styles.typeButtonContent}>
                <MaterialCommunityIcons
                  name="trending-down"
                  size={18}
                  color={type === 'gasto' ? '#FFFFFF' : theme.textSecondary}
                />
                <Text style={type === 'gasto' ? styles.typeTextActive : styles.typeText}>{t('Gastos')}</Text>
              </View>
            </Pressable>
            <Pressable
              style={[styles.typeButton, type === 'ingreso' && styles.typeButtonActiveIncome]}
              onPress={() => setType('ingreso')}
            >
              <View style={styles.typeButtonContent}>
                <MaterialCommunityIcons
                  name="trending-up"
                  size={18}
                  color={type === 'ingreso' ? '#FFFFFF' : theme.textSecondary}
                />
                <Text style={type === 'ingreso' ? styles.typeTextActive : styles.typeText}>{t('Ingresos')}</Text>
              </View>
            </Pressable>
          </View>

          <View style={[styles.inputContainer, { backgroundColor: theme.surfaceMuted, borderColor: theme.border }]}>
            <MaterialCommunityIcons name="currency-usd" size={20} color={theme.textSecondary} style={styles.inputIcon} />
            <TextInput
              style={[styles.input, { color: theme.text }]}
              placeholder="Monto"
              accessibilityLabel="Monto"
              keyboardType="decimal-pad"
              returnKeyType="next"
              value={amount}
              onChangeText={(value) => {
                setAmount(value.replace(/[^0-9.,]/g, ''));
                if (amountError) setAmountError('');
              }}
              onBlur={() => {
                const numericAmount = parseFloat(amount.replace(',', '.'));
                if (amount && (!Number.isFinite(numericAmount) || numericAmount <= 0)) {
                  setAmountError('Ingresa un monto mayor que cero.');
                }
              }}
              placeholderTextColor="#94A3B8"
            />
          </View>
          {amountError ? <Text style={styles.errorText}>{amountError}</Text> : null}

          <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.categoryScroll}>
            {CATEGORIES.map((c) => (
              <Pressable
                key={c}
                style={[styles.categoryChip, { backgroundColor: theme.surfaceMuted, borderColor: theme.border }, category === c && { backgroundColor: `${accentColor}18`, borderColor: accentColor }]}
                onPress={() => setCategory(c)}
              >
                <View style={styles.categoryChipContent}>
                  <MaterialCommunityIcons
                    name={CATEGORY_LABELS[c].emoji === '💰' ? 'cash' : 'tag-outline'}
                    size={16}
                    color={category === c ? accentColor : theme.textSecondary}
                  />
                  <Text style={[styles.categoryChipText, { color: theme.textSecondary }, category === c && { color: accentColor }]}>
                    {t(CATEGORY_LABELS[c].label)}
                  </Text>
                </View>
              </Pressable>
            ))}
          </ScrollView>

          <View style={[styles.inputContainer, { backgroundColor: theme.surfaceMuted, borderColor: theme.border }]}>
            <MaterialCommunityIcons name="note-text-outline" size={20} color={theme.textSecondary} style={styles.inputIcon} />
            <TextInput
              style={[styles.input, { color: theme.text }]}
              placeholder="Nota (opcional)"
              accessibilityLabel="Nota opcional"
              returnKeyType="done"
              value={note}
              onChangeText={setNote}
              onSubmitEditing={Keyboard.dismiss}
              placeholderTextColor="#94A3B8"
            />
          </View>

          <Pressable
            style={[styles.submitButton, isSubmitting && styles.submitButtonDisabled]}
            onPress={handleSubmit}
            disabled={isSubmitting}
          >
            <Text style={styles.submitText}>{isSubmitting ? 'Guardando...' : 'Guardar'}</Text>
          </Pressable>
        </KeyboardAvoidingView>
        </BottomSheetView>
      </TouchableWithoutFeedback>
    </BottomSheetModal>
  );
}

const styles = StyleSheet.create({
  contentContainer: {
    flex: 1,
    paddingHorizontal: 20,
    paddingBottom: Platform.OS === 'ios' ? 40 : 24,
  },
  handleBar: {
    width: 44,
    height: 5,
    backgroundColor: '#E2E8F0',
    borderRadius: 3,
    alignSelf: 'center',
    marginBottom: 20,
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 24,
  },
  title: {
    fontSize: 20,
    fontWeight: '800',
    color: '#0F172A',
    letterSpacing: -0.3,
  },
  subtitle: {
    fontSize: 12,
    color: '#64748B',
    marginTop: 2,
    fontWeight: '500',
  },
  typeSwitch: {
    flexDirection: 'row',
    marginBottom: 20,
    gap: 8,
  },
  typeButton: {
    flex: 1,
    padding: 12,
    borderRadius: 12,
    backgroundColor: '#F0F0F5',
    alignItems: 'center',
  },
  typeButtonContent: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
  },
  typeButtonActiveExpense: { backgroundColor: '#EF4444' },
  typeButtonActiveIncome: { backgroundColor: '#10B981' },
  typeText: { color: '#5A5A66', fontWeight: '600' },
  typeTextActive: { color: '#FFFFFF', fontWeight: '700' },
  inputContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    borderWidth: 1,
    borderColor: '#E4E4EC',
    borderRadius: 12,
    paddingHorizontal: 12,
    marginBottom: 16,
    backgroundColor: '#FFFFFF',
    height: 50,
  },
  inputIcon: {
    marginRight: 10,
  },
  input: {
    flex: 1,
    fontSize: 15,
    color: '#0F172A',
  },
  categoryScroll: { marginBottom: 20 },
  categoryChip: {
    paddingVertical: 8,
    paddingHorizontal: 12,
    backgroundColor: '#F0F0F5',
    borderRadius: 20,
    marginRight: 8,
  },
  categoryChipContent: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
  },
  categoryChipText: {
    fontSize: 13,
    color: '#64748B',
  },
  categoryChipTextActive: {
    color: '#4F46E5',
    fontWeight: '700',
  },
  categoryChipActive: { backgroundColor: '#E0E7FF' },
  submitButton: {
    backgroundColor: '#6366F1',
    padding: 16,
    borderRadius: 14,
    alignItems: 'center',
    marginTop: 10,
    marginBottom: 20,
  },
  submitButtonDisabled: {
    opacity: 0.6,
  },
  errorText: {
    color: '#EF4444',
    fontSize: 12,
    marginTop: -10,
    marginBottom: 12,
  },
  submitText: { color: '#FFFFFF', fontWeight: '800', fontSize: 16 },
});
